-- Vidage des tables avant insertion (base vide après schéma)
TRUNCATE users, pokemons, shop_items, badges, arenas, active_events, types RESTART IDENTITY CASCADE;

-- Types
SELECT setval('types_id_seq', (SELECT COALESCE(MAX(id), 1) FROM types));

-- Pokemons
SELECT setval('pokemons_id_seq', (SELECT COALESCE(MAX(id), 1) FROM pokemons));

-- Pokemon types
SELECT setval('pokemon_types_id_seq', (SELECT COALESCE(MAX(id), 1) FROM pokemon_types));

-- Pokemon resistances
SELECT setval('pokemon_resistances_id_seq', (SELECT COALESCE(MAX(id), 1) FROM pokemon_resistances));

-- Pokemon evolutions
SELECT setval('pokemon_evolutions_id_seq', (SELECT COALESCE(MAX(id), 1) FROM pokemon_evolutions));

-- Shop items
SELECT setval('shop_items_id_seq', (SELECT COALESCE(MAX(id), 1) FROM shop_items));

-- Badges
SELECT setval('badges_id_seq', (SELECT COALESCE(MAX(id), 1) FROM badges));

-- Arenas
SELECT setval('arenas_id_seq', (SELECT COALESCE(MAX(id), 1) FROM arenas));

-- Arena teams
SELECT setval('arena_teams_id_seq', (SELECT COALESCE(MAX(id), 1) FROM arena_teams));

-- Fin du seed